import{_ as t,l as r,o,c as l,v as e,p as n,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Poisson 与负二项良率模型","description":"","frontmatter":{"title":"Poisson 与负二项良率模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/yield-models.md","filePath":"litho/yield-models.md","lastUpdated":1789023840000}'),P={name:"litho/yield-models.md"};function A(c,a,_,m,E,D){const s=r("Mermaid");return o(),l("div",null,[a[1]||(a[1]=e('<h1 id="poisson-与负二项良率模型" tabindex="-1">Poisson 与负二项良率模型 <a class="header-anchor" href="#poisson-与负二项良率模型" aria-label="Permalink to &quot;Poisson 与负二项良率模型&quot;">​</a></h1><div class="epigraph"><p>良率先是一张缺陷密度的概率：Poisson 假定管芯间独立均匀；簇生和晶圆间不齐用负二项把方差撑开。</p><footer>—— 对照 Stapper 对 IC 良率与负二项的经典工作；半导体良率模型教材通称</footer></div><p><a href="/litho/virtual-metrology">上一课</a>结束控制环。缺口是出货概率：缺陷如何把管芯杀死。光刻主干已多次点名随机与系统失效；本课钉经典良率函数。关键面积如何把布局变成有效缺陷灵敏度，留给<a href="/litho/critical-area">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Poisson 模型：\\(Y = e^{-DA}\\)，\\(D\\) 缺陷密度，\\(A\\) 有效面积。它低估实际良率时，往往是因为缺陷簇生（一次颗粒打一簇管芯）或 \\(D\\) 在晶圆间波动。负二项（Murphy、Seeds、Stapper 等形式）引入聚类参数，同样平均 \\(D\\) 下良率更高——因为缺陷挤在少数管芯上。</p><p>缺口是<strong>模型是计数统计，不是工艺物理</strong>。把 Poisson 倒过来估 \\(D\\)，再当光刻缺陷密度去拧剂量，会把系统热点当成随机颗粒。下一课关键面积、再下一课系统对随机，就是为了拆开。</p><h3 id="大管芯更疼" tabindex="-1">大管芯更疼 <a class="header-anchor" href="#大管芯更疼" aria-label="Permalink to &quot;大管芯更疼&quot;">​</a></h3><p>同一 \\(D\\)，面积翻倍，Poisson 良率指数下降。这是芯片尺寸与缺陷密度的第一课，也是为何边缘部分场的管芯统计要分开：它们的有效 \\(A\\) 和 \\(D\\) 都不同。</p><p><span class="marginnote">拟合聚类参数需要足够失败管芯。良率 99% 时，负二项与 Poisson 在工程上难分，却会在下一节点面积增大时分叉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：探针图、缺陷检测计数（需复检课校正）。拟合：Poisson 对负二项，看残差是否空间相关——相关则系统或簇生。分层：按层、按缺陷类型。与控制：APC 不直接进 \\(Y\\) 公式；良率模型吃的是缺陷与参数分布。</p><p>拟合前先做系统叠图。空间相关强时，先拆系统账，再对残差拟合 \\(D\\)。Stapper 的负二项处理的是随机簇生，不是把 OPC 热点平均进聚类参数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Poisson 来自稀有独立事件。负二项可理解为 Gamma 混合的 Poisson（\\(D\\) 随机）。空间上，簇生造成相邻管芯同死。图形化随机（缺孔）更接近独立 Bernoulli，用 Poisson 面积要换成「每孔失败率 × 孔数」，不是颗粒 \\(DA\\)——随机良率课再写。</p>',14)),(o(),n(h,null,{default:i(()=>[p(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%BC%BA%E9%99%B7%E5%AF%86%E5%BA%A6%20D%22%5D%20--%3E%20POI%5B%22Poisson%20Y%3De%5E%7B-DA%7D%22%5D%0A%20%20A%5B%22%E6%9C%89%E6%95%88%E9%9D%A2%E7%A7%AF%20A%22%5D%20--%3E%20POI%0A%20%20CL%5B%22%E8%81%9A%E7%B1%BB%20%2F%20D%20%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20NB%5B%22%E8%B4%9F%E4%BA%8C%E9%A1%B9%22%5D%0A%20%20POI%20--%3E%20FIT%5B%22%E6%8E%A2%E9%92%88%E5%9B%BE%E6%8B%9F%E5%90%88%22%5D%0A%20%20NB%20--%3E%20FIT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>Poisson 是独立均匀的基线；空间相关应先拆系统，再对残差拟合聚类。倒推 \\(D\\) 不能直接拧扫描机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型不区分桥连来自 OPC 还是颗粒。不发明新 arXiv。不把某厂 \\(D\\) 数字当公开规格。</p><p>后课默认：随机颗粒可用 Poisson/负二项做账；布局灵敏度用关键面积。下一课把 \\(A\\) 从芯片面积改成关键面积。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Poisson 是独立均匀缺陷的基线；簇生用负二项。</li><li>倒推 \\(D\\) 不能直接当光刻旋钮。</li><li>大管芯与边缘管芯要分层拟合。</li><li>拟合前先做系统叠图，相关残差再进负二项。</li><li>出处：Stapper 良率与负二项；半导体良率教材通称。</li></ul>',6))])}const f=t(P,[["render",A]]);export{B as __pageData,f as default};
